def design(X):
    n=len(X);Z=(X-center)/scale
    cols=[np.ones(n)];tags=[["intercept"]];bases=[]
    for j in range(20):
        cols.append(Z[:,j]);tags.append([j,"linear"])
        if j==0 or j>=10:
            knots=np.arange(-3,4,1) if j==0 else np.arange(1,10,1)
            for k in knots:
                t=(k-center[j])/scale[j];m=(1-t)**2/4
                cols.append(np.maximum(Z[:,j]-t,0)-m);tags.append([j,"hinge",float(k)])
        bj=[(Z[:,j],None)]
        if j==0 or j>=10:
            knots2=[0.] if j==0 else ([2.5,5.,7.5] if j==12 else [5.])
            for k in knots2:
                t=(k-center[j])/scale[j];m=(1-t)**2/4;a=(2-3*t+t**3)/4
                bj.append((np.maximum(Z[:,j]-t,0)-m-a*Z[:,j],float(k)))
        bases.append(bj)
    cut=len(cols)
    for j in range(20):
        for k in range(j+1,20):
            for v,t in bases[j]:
                for w,u in bases[k]:
                    cols.append(v*w);tags.append([j,k,t,u])
    return np.column_stack(cols),tags,cut
